// Базовые элементы JS по заданию 2.2

// 1. let и const
const studentName = "Лисай"; // замени на свою фамилию
const groupName = "УИР";    // замени на свою группу
let score = 0;

// 2. Массив
const subjects = ["Математика", "Менеджмент", "Программирование"];

// 3. Объект
const student = {
  name: studentName,
  group: groupName,
  subjects: subjects
};

// 4. Цикл for
for (let i = 0; i < subjects.length; i++) {
  score += 10;
  console.log(`Предмет ${i + 1}: ${subjects[i]}, текущий счёт: ${score}`);
}

// 5. if/else
let grade;
if (score >= 30) {
  grade = "Отлично";
} else if (score >= 20) {
  grade = "Хорошо";
} else {
  grade = "Удовлетворительно";
}

// Добавляем результат в payload
const result = {
  payload: studentName,
  group: groupName,
  totalScore: score,
  grade: grade,
  student: student
};

// Возвращаем результат
return [{ json: result }];
